/**
 * SearchFacets
 *
 * How many of all the matching moments are in each namespace, speaker, emotion and recording (up to 50 of each,
 * most first), and the kinds of object seen in the recordings they're in. Text on screen has no speaker or emotion.
 */
export type SearchFacets = {
  /**
   * Moments
   *
   * the matching moments counted: all of them, unless `partial`
   */
  moments: number;
  /**
   * Partial
   *
   * more than 20,000 moments match; the counts cover 20,000 of them
   */
  partial: boolean;
  /**
   * Namespaces
   */
  namespaces?: Array<FacetCount>;
  /**
   * Speakers
   */
  speakers?: Array<SpeakerFacet>;
  /**
   * Emotions
   */
  emotions?: Array<FacetCount>;
  /**
   * Recordings
   */
  recordings?: Array<RecordingFacet>;
  /**
   * Objects
   */
  objects?: Array<ObjectFacet>;
  [key: string]: unknown;
};

/**
 * SearchHit
 */
export type SearchHit = {
  /**
   * Id
   *
   * segment id (int) for transcript hits, OCR span or file line id (str) for the others
   */
  id: number | string;
  /**
   * Recording Id
   */
  recording_id: number;
  /**
   * Idx
   */
  idx?: number | null;
  /**
   * T0
   *
   * ms; None for a line of a file that doesn't say when its lines are
   */
  t0: number | null;
  /**
   * T1
   */
  t1: number | null;
  /**
   * Emotion
   */
  emotion?: string | null;
  /**
   * Speaker Id
   */
  speaker_id?: number | null;
  /**
   * Speaker
   */
  speaker?: string | null;
  /**
   * Title
   */
  title?: string | null;
  /**
   * Recorded At
   */
  recorded_at?: string | null;
  /**
   * Namespace
   */
  namespace?: string | null;
  /**
   * Snippet
   *
   * HTML: escaped text with <mark> around matches
   */
  snippet: string;
  /**
   * Source
   *
   * "said" (transcript), "screen" (text on screen in a video), "file" (a line of a supplementary file), "page" (text on a page of a document or an image, whose times are only a reading pace), "object" (a kind of object seen in a video, a document or an image, where it's first seen; its snippet is the kind) or "described" (what a model that can see said a shot of a video, or a page, shows)
   */
  source: "said" | "screen" | "file" | "page" | "object" | "described";
  /**
   * Frame
   *
   * screen, object and described hits: signed link to the video frame or the page
   */
  frame?: string | null;
  /**
   * Box
   *
   * screen, page and object hits: where it is on the frame or the page ([x, y, w, h] fractions)
   */
  box?: unknown;
  /**
   * Page
   *
   * page hits, and object and described hits on pages: which page (from 0)
   */
  page?: number | null;
  /**
   * File
   *
   * file hits: the supplementary file the line is in
   */
  file?: number | null;
  /**
   * File Role
   *
   * file hits: its role (transcript, captions, translation or index)
   */
  file_role?: string | null;
  /**
   * File Label
   *
   * file hits: its label, or its name
   */
  file_label?: string | null;
  /**
   * Line
   *
   * file hits: which of its lines (from 0)
   */
  line?: number | null;
  /**
   * Match
   *
   * how it was found: by the query's "words" (BM25), by "meaning" (a passage an embedding model finds alike; shown at its line that fits best), or "both"
   */
  match?: "words" | "meaning" | "both";
  /**
   * Similarity
   *
   * found by meaning: how alike the passage is to the query (cosine, up to 1)
   */
  similarity?: number | null;
  [key: string]: unknown;
};

