  /**
   * Merges
   */
  merges: Array<SpeakerMerge>;
  /**
   * Links
   */
  links: Array<SpeakerLink>;
  /**
   * Cross
   *
   * likely the same voice in another shared namespace you can read (speakers.cross_namespace: suggest), best first; not linked, and not said to be different
   */
